      "You always advance one rank at a time. Even if you meet the requirements for V5 today, the system promotes you to V3 first, then to V4 on the next qualifying event, then V5 — so every rank's reward and unlocks are released in order.",
    s3RuleBTitle: "Once earned, always yours",
    s3RuleBBody:
      "Your rank is permanent. If team volume later shrinks or a teammate's rank drops, you keep everything you've already unlocked — wider extended royalty, peer bonus, leadership pool seat, cultivation bonus.",
    s4Title: "What each rank unlocks",
    s4Intro:
      "Each rank adds rewards on top of the ones you already have.",
    unlock1Label: "Wider extended royalty",
    unlock1Body:
      "Each rank widens the reach of your extended-network royalty. V0 earns from direct invites only; mid ranks pull in friends-of-friends; V10+ has unlimited extended reach.",
    unlock2Label: "Peer Bonus (from V3)",
    unlock2Body:
      "A 5% bonus paid when teammates at your same rank or above make qualifying purchases — rewards leaders who build other leaders.",
    unlock3Label: "Leadership Pool seat (from V3)",
    unlock3Body:
      "A weekly share of 5% of total platform volume. Your vote count doubles every rank — V3 = 1 vote, V12 = 512 votes.",
    unlock5Label: "Cultivation bonus to your sponsor",
    unlock5Body:
      "When you reach a new rank, your direct sponsor receives a one-time UVT reward — the system rewards mentorship.",
    s5Title: "Worked example: Alice advances V3 → V4",
    s5Intro:
      "A walk-through of one user's actual journey, with real numbers and timing.",
    s5StartLabel: "Starting point",
    s5StartBody:
      "Alice is currently V3 Captain. Her team volume sits at $22,000.00. Her two V1 direct invites helped her qualify when she reached V3 six months ago.",
    s5Phase1Title: "Phase 1 — Existing invites grow",
    s5Phase1Body:
      "Alice's two V1 invites (Bob and Carol) each build out their own teams. Both cross the $5,000.00 team-volume mark and auto-promote to V2. Alice receives a +2,000.00 UVT cultivation bonus for each promotion.",
    s5Phase2Title: "Phase 2 — A new invite matures",
    s5Phase2Body:
      "Alice invites David, who signs up and buys his first UVELBox. David grows his own small team and also reaches V2. Alice now has 3 direct invites at V2 (Bob, Carol, David) — and her team-volume total has climbed to about $52,000.00 from cumulative orders across the network.",
    s5Phase3Title: "Phase 3 — Promotion trigger",
    s5Phase3Body:
      "David places one more UVELBox order. The system re-checks Alice's rank progress.",
    s5TriggerLabel: "Promotion fires instantly",
    s5TriggerBody:
      "Team volume $52,300.00 ≥ $50,000.00 ✓ AND direct invites at V2+ count = 3 ≥ 3 ✓. Both conditions are satisfied in the same event — Alice is auto-promoted to V4 Commander on that exact frame.",
    s5UnlockLabel: "What Alice gets at V4",
    s5Unlock1:
      "Extended-network royalty reach widens — additional downstream orders now flow into her monthly royalty at the V4 rate",
    s5Unlock2:
      "Leadership Pool seat goes from 1 vote to 2 votes (effective at the next weekly settlement)",
    s5Unlock3:
      "Extended-network royalty depth widens by one more layer — she now earns royalty on orders from her 5th downstream layer",
    s5Unlock4:
      "Alice's own sponsor (Sarah) receives a +50,000.00 UVT cultivation bonus for her advancement",
    faqTitle: "Common questions",
    faqQ1: "Can I skip ranks to V5 or higher in one go?",
    faqA1:
      "No — promotions are always one step at a time. This ensures every rank's reward and unlocks are released in order. If you meet several ranks' conditions simultaneously, you'll move up one rank per qualifying event.",
    faqQ2: "What if my team shrinks after I reach a rank?",
    faqA2:
      "Whether your rank is kept follows the current rank rules. See the rank page.",
    faqQ3: "How do I see how close I am to the next rank?",
    faqA3:
      "The /team/rank page shows your current rank, a percentage progress bar to the next rank, and a checklist of what you still need.",
    ctaBack: "Got it · see my rank progress",
